CREATE TABLE calendar (
    calendar_date DATE PRIMARY KEY
);

CREATE PROCEDURE FillCalendar()
BEGIN
    -- Declare variables with a non-reserved name
    DECLARE current_dt DATE; -- Changed variable name from current_date

    -- Initialize variables
    SET current_dt = '2010-01-01';

    -- Start transaction for better performance
    START TRANSACTION;

    WHILE current_dt <= DATE('2014-12-31') DO
        -- Check if the current date is a weekend or holiday
        IF (DAYOFWEEK(current_dt) = 1 OR DAYOFWEEK(current_dt) = 7) OR current_dt IN (
            '2010-01-01', '2010-07-04', '2010-11-11', '2010-12-25',
            '2011-01-01', '2011-07-04', '2011-11-11', '2011-12-25',
            '2012-01-01', '2012-07-04', '2012-11-11', '2012-12-25',
            '2013-01-01', '2013-07-04', '2013-11-11', '2013-12-25',
            '2014-01-01', '2014-07-04', '2014-11-11', '2014-12-25'
        ) THEN
            INSERT INTO calendar (calendar_date) VALUES (current_dt);
        END IF;

        -- Move to the next day
        SET current_dt = DATE_ADD(current_dt, INTERVAL 1 DAY);
    END WHILE;

    COMMIT;
END

DROP PROCEDURE IF EXISTS delcolumn;

CREATE PROCEDURE delcolumn(
	tbname varchar(100)
)
BEGIN
	DECLARE finished INTEGER DEFAULT 0;
	DECLARE colname varchar(100) DEFAULT "";
	DECLARE curcol
		CURSOR FOR
			SELECT COLUMN_NAME
			FROM INFORMATION_SCHEMA.COLUMNS
			WHERE TABLE_NAME = tbname;
	DECLARE CONTINUE HANDLER
		FOR NOT FOUND SET finished = 1;
	OPEN curcol;

	getcol: LOOP
		FETCH curcol INTO colname;
		IF finished = 1 THEN
			LEAVE getcol;
		END IF;
		SET @sql = CONCAT('SELECT COUNT(`',colname,'`) INTO @count FROM `',tbname,'`;');
		PREPARE stmt2 FROM @sql;
		EXECUTE stmt2;
		IF @count = 0 THEN
		SET @sql = CONCAT('ALTER TABLE `',tbname,'` DROP COLUMN `',colname,'`');
		PREPARE stmt2 FROM @sql;
		EXECUTE stmt2;
		END IF;
	END LOOP getcol;
	CLOSE curcol;
END;

